export function camel_to_snake(s: string): string {
  let out = "";
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    const isUpper = ch >= "A" && ch <= "Z";
    if (isUpper) {
      if (i > 0) out += "_";
      out += ch.toLowerCase();
    } else {
      out += ch;
    }
  }
  return out;
}
